package com.ruoyi.majorpilot.privacy;

import com.fasterxml.jackson.databind.*;
import com.ruoyi.majorpilot.auth.*;
import com.ruoyi.majorpilot.security.RateLimits;
import com.ruoyi.majorpilot.shared.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Dedicated V8 test schema. Request acceptance is real; all generated files stay in @TempDir. */
@EnabledIfEnvironmentVariable(named="MP_RUN_MYSQL_TESTS",matches="true")
class PrivacyJobsMySqlTest {
    static JdbcTemplate db;static TransactionTemplate tx;static ObjectMapper mapper;static StudentPasswords passwords;
    static final String PASSWORD="synthetic-privacy-password-73";
    @TempDir Path temporary;
    StudentPrincipal student,other;PrivacyStore store;PrivateObjectStore files;PrivacyService service;AccountDeletionOwnershipGuard guard;AccountDeletionStages stages;PrivacyJobs jobs;
    final List<PrivacyJobs> workers=new ArrayList<>();final List<String> receipts=new ArrayList<>();
    @BeforeAll static void database(){String url=System.getenv("MP_DB_URL");if(url==null||!url.startsWith("jdbc:mysql://127.0.0.1:13306/majorpilot?"))throw new IllegalStateException("Dedicated test database required");var source=new DriverManagerDataSource(url.replace("/majorpilot?","/majorpilot_test?"),System.getenv("MP_DB_USERNAME"),System.getenv("MP_DB_PASSWORD"));db=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);passwords=new StudentPasswords();assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM flyway_schema_history WHERE version='8' AND success=1",Integer.class));}
    StudentPrincipal createStudent(){String id=PublicIds.next(),email="privacy-worker-"+id+"@example.invalid";db.update("INSERT INTO mp_student_account(public_id,email_normalized,email_display,password_hash,status,analytics_exclusion_code) VALUES(?,?,?,?,'ACTIVE','TEST')",id,email,email,passwords.hash(PASSWORD));return new StudentPrincipal(db.queryForObject("SELECT id FROM mp_student_account WHERE public_id=?",Long.class,id),id,"ACTIVE");}
    @BeforeEach void fixture()throws Exception{student=createStudent();other=createStudent();store=new PrivacyStore(db,tx,mapper);files=new PrivateObjectStore(temporary.toRealPath().toString());guard=spy(new AccountDeletionOwnershipGuard(db));stages=new AccountDeletionStages(store,files,guard);service=new PrivacyService(store,new IdempotencyService(db,tx,new Secrets("synthetic-p7-privacy-".repeat(4)),mapper),mock(RateLimits.class),passwords,new StudentSessions(db),files);jobs=worker(files,new PersonalExportWriter(db,mapper),stages);}
    PrivacyJobs worker(PrivateObjectStore objectStore,PersonalExportWriter writer,AccountDeletionStages deletion){var value=new PrivacyJobs(store,objectStore,writer,deletion);workers.add(value);return value;}
    @AfterEach void cleanup(){workers.forEach(PrivacyJobs::stop);for(var owner:List.of(student,other)){long id=owner.internalId();db.update("DELETE FROM mp_idempotency_record WHERE owner_student_id=?",id);db.update("DELETE FROM mp_background_job WHERE owner_student_id=?",id);db.update("DELETE FROM mp_student_data_export WHERE student_id=?",id);db.update("DELETE FROM mp_account_deletion_request WHERE student_id=?",id);db.update("DELETE FROM mp_student_session WHERE student_id=?",id);db.update("DELETE FROM mp_email_token WHERE student_id=?",id);db.update("DELETE FROM mp_student_account WHERE id=?",id);}for(String receipt:receipts)db.update("DELETE FROM mp_account_deletion_request WHERE receipt_id=?",receipt);}
    static String key(){return UUID.randomUUID().toString();}
    PrivacyDtos.ExportStatus request(){return service.requestExport(student,new PrivacyDtos.ExportRequest("FULL_PERSONAL_EXPORT"),key());}
    PrivacyDtos.IssuedDeletion deletion(){var issued=service.requestDeletion(student,key());receipts.add(issued.status().receiptId());return issued;}
    void confirm(PrivacyDtos.IssuedDeletion issued){service.confirmDeletion(student,issued.status().requestId(),new PrivacyDtos.DeletionConfirm(PASSWORD),key());}
    PrivacyJobs.Lease claim(PrivacyJobs worker,String name){var lease=worker.claim(name);assertNotNull(lease);assertEquals(student.internalId(),lease.student(),"Must not claim another fixture's job");return lease;}
    void due(long job){db.update("UPDATE mp_background_job SET lease_until=UTC_TIMESTAMP(3)-INTERVAL 1 SECOND,available_at=UTC_TIMESTAMP(3) WHERE id=?",job);}
    JsonNode checkpoint(long job){return store.node(db.queryForObject("SELECT checkpoint_json FROM mp_background_job WHERE id=?",String.class,job));}

    @Test void publishesRealPrivateZipAndIgnoresOtherJobTypesThenExpiresByStatus(){
        db.update("INSERT INTO mp_background_job(public_id,job_type,business_key,target_type,target_id,available_at) VALUES(?,'RETENTION_CLEANUP',?,'RETENTION_POLICY',0,UTC_TIMESTAMP(3))",PublicIds.next(),"privacy-foreign-type:"+student.publicId());
        try{var requested=request();var lease=claim(jobs,"privacy-real-zip");assertEquals("STUDENT_EXPORT",lease.type());jobs.process(lease);assertEquals("READY",service.exportStatus(student,requested.exportId()).status());byte[] bytes=service.download(student,requested.exportId());assertTrue(bytes.length>100);assertEquals('P',bytes[0]);assertEquals('K',bytes[1]);assertEquals(1,checkpoint(lease.job()).path("artifactKeys").size());assertEquals("SUCCEEDED",db.queryForObject("SELECT status FROM mp_background_job WHERE id=?",String.class,lease.job()));assertNull(jobs.claim("no-other-type"));db.update("UPDATE mp_student_data_export SET expires_at=UTC_TIMESTAMP(3)-INTERVAL 1 SECOND WHERE id=?",lease.target());assertEquals("EXPIRED",service.exportStatus(student,requested.exportId()).status());assertEquals(404,assertThrows(ApiException.class,()->service.download(student,requested.exportId())).status);}finally{db.update("DELETE FROM mp_background_job WHERE business_key=? AND job_type='RETENTION_CLEANUP' AND owner_student_id IS NULL","privacy-foreign-type:"+student.publicId());}
    }
    @Test void newWorkerResumesExpiredLeaseAndOldWorkerCannotPublishOrFailItsReplacement(){var accepted=request();var first=claim(jobs,"old-export");due(first.job());var resumed=worker(files,new PersonalExportWriter(db,mapper),stages);var second=claim(resumed,"new-export");assertEquals(first.generation()+1,second.generation());assertFalse(jobs.heartbeat(first));jobs.process(first);jobs.fail(first,"OLD_FAILURE");assertEquals("PROCESSING",service.exportStatus(student,accepted.exportId()).status());assertEquals("new-export",db.queryForObject("SELECT worker_id FROM mp_background_job WHERE id=?",String.class,first.job()));resumed.process(second);assertEquals("READY",service.exportStatus(student,accepted.exportId()).status());assertEquals(2,db.queryForObject("SELECT attempt_count FROM mp_background_job WHERE id=?",Integer.class,first.job()));}
    @Test void diskFailureKeepsDurableArtifactTrackingAndExhaustsOnlyExportsAtThree()throws Exception{
        var unavailable=new PrivateObjectStore(temporary.toRealPath().toString()){@Override public Stored write(String key,byte[] bytes){super.write(key,bytes);throw new IllegalStateException("synthetic write acknowledgement loss");}@Override public void delete(String key){throw new IllegalStateException("synthetic disk delete failure");}};
        var broken=worker(unavailable,new PersonalExportWriter(db,mapper),new AccountDeletionStages(store,unavailable,guard));var accepted=request();long job=0;
        for(int i=1;i<=3;i++){var lease=claim(broken,"disk-attempt-"+i);job=lease.job();broken.process(lease);assertEquals(i,checkpoint(job).path("artifactKeys").size());assertEquals(i,db.queryForObject("SELECT attempt_count FROM mp_background_job WHERE id=?",Integer.class,job));if(i<3)due(job);}
        assertEquals("FAILED",service.exportStatus(student,accepted.exportId()).status());assertNull(broken.claim("no-fourth-export"));for(var file:checkpoint(job).path("artifactKeys"))assertTrue(files.read(file.asText()).length>100);
        var issued=deletion();confirm(issued);var deletionLease=claim(jobs,"cleanup-tracked-files");jobs.process(deletionLease);assertEquals("COMPLETED",service.receipt(issued.status().receiptId(),issued.secret()).status());try(var remaining=java.nio.file.Files.list(temporary.resolve("student"))){assertFalse(remaining.anyMatch(p->p.getFileName().toString().endsWith(".zip")));}
    }
    @Test void localFileWriteHoldsStudentLockWhileIndependentHeartbeatCanRenew()throws Exception{
        var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var order=new AtomicInteger();var written=new AtomicInteger();var confirmed=new AtomicInteger();
        var slow=new PrivateObjectStore(temporary.toRealPath().toString()){@Override public Stored write(String key,byte[] bytes){assertTrue(TransactionSynchronizationManager.isActualTransactionActive());entered.countDown();await(release);var result=super.write(key,bytes);written.set(order.incrementAndGet());return result;}};
        var worker=worker(slow,new PersonalExportWriter(db,mapper),new AccountDeletionStages(store,slow,guard));var export=request();var issued=deletion();var lease=claim(worker,"locked-file-write");
        try(var pool=Executors.newFixedThreadPool(3)){var processing=pool.submit(()->worker.process(lease));assertTrue(entered.await(3,TimeUnit.SECONDS));var deleting=pool.submit(()->{confirm(issued);confirmed.set(order.incrementAndGet());});assertThrows(TimeoutException.class,()->deleting.get(100,TimeUnit.MILLISECONDS));assertTrue(pool.submit(()->worker.heartbeat(lease)).get(2,TimeUnit.SECONDS));release.countDown();processing.get(5,TimeUnit.SECONDS);deleting.get(5,TimeUnit.SECONDS);assertTrue(written.get()>0&&written.get()<confirmed.get());assertEquals("EXPIRED",db.queryForObject("SELECT status FROM mp_student_data_export WHERE public_id=?",String.class,export.exportId()));assertEquals(403,assertThrows(ApiException.class,()->service.download(student,export.exportId())).status);}finally{release.countDown();}
    }
    @Test void confirmationBeforeProcessingPreventsLateFileCreationAndSessionReuse(){var export=request();var lease=claim(jobs,"before-confirm");String session=new StudentSessions(db).issue(student.internalId());var issued=deletion();confirm(issued);var checked=spy(files);var late=worker(checked,new PersonalExportWriter(db,mapper),new AccountDeletionStages(store,checked,guard));late.process(lease);verify(checked,never()).write(anyString(),any());assertFalse(late.heartbeat(lease));assertThrows(ApiException.class,()->new StudentSessions(db).authenticate(session));assertEquals("EXPIRED",db.queryForObject("SELECT status FROM mp_student_data_export WHERE public_id=?",String.class,export.exportId()));}
    @Test void leaseExpiryDuringFileWriteRollsBackPublicationAndNewLeaseGetsANewArtifact()throws Exception{
        var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var slow=new PrivateObjectStore(temporary.toRealPath().toString()){@Override public Stored write(String key,byte[] bytes){var written=super.write(key,bytes);entered.countDown();await(release);return written;}};var old=worker(slow,new PersonalExportWriter(db,mapper),stages);var export=request();var lease=claim(old,"lease-expires-in-write");
        try(var pool=Executors.newSingleThreadExecutor()){var processing=pool.submit(()->old.process(lease));assertTrue(entered.await(3,TimeUnit.SECONDS));due(lease.job());release.countDown();processing.get(5,TimeUnit.SECONDS);}finally{release.countDown();}
        assertEquals("PROCESSING",service.exportStatus(student,export.exportId()).status());String staleKey=checkpoint(lease.job()).path("artifactKeys").get(0).asText();assertThrows(IllegalStateException.class,()->files.read(staleKey));var current=claim(jobs,"fresh-lease-after-expiry");jobs.process(current);assertEquals("READY",service.exportStatus(student,export.exportId()).status());assertEquals(2,checkpoint(lease.job()).path("artifactKeys").size());assertNotEquals(staleKey,db.queryForObject("SELECT object_key FROM mp_student_data_export WHERE id=?",String.class,current.target()));
    }
    @Test void deletionResumesCommittedStagesOnNewWorkerAndOnlyFilesRevalidatesFullGraph(){
        var issued=deletion();confirm(issued);var first=claim(jobs,"delete-before-crash");assertFalse(jobs.deleteStage(first));assertEquals("METADATA",db.queryForObject("SELECT current_stage FROM mp_account_deletion_request WHERE id=?",String.class,first.target()));verify(guard,times(1)).validate(student.internalId());due(first.job());var replacement=worker(files,new PersonalExportWriter(db,mapper),stages);var next=claim(replacement,"delete-after-crash");assertTrue(jobs.deleteStage(first));assertFalse(jobs.heartbeat(first));replacement.process(next);verify(guard,times(1)).validate(student.internalId());assertEquals("COMPLETED",service.receipt(issued.status().receiptId(),issued.secret()).status());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_student_account WHERE id=?",Integer.class,student.internalId()));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM mp_student_account WHERE id=?",Integer.class,other.internalId()));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_background_job WHERE id=?",Integer.class,first.job()));assertNull(db.queryForObject("SELECT student_id FROM mp_account_deletion_request WHERE id=?",Long.class,first.target()));
    }
    @Test void deletionFileFailureRetainsRowsAndRetriesPastOrdinaryThreeAttemptLimit()throws Exception{
        var export=request();var exportLease=claim(jobs,"publish-before-delete");jobs.process(exportLease);String key=db.queryForObject("SELECT object_key FROM mp_student_data_export WHERE public_id=?",String.class,export.exportId());var issued=deletion();confirm(issued);
        var brokenFiles=new PrivateObjectStore(temporary.toRealPath().toString()){@Override public void delete(String logical){throw new IllegalStateException("synthetic inaccessible file");}};var broken=worker(brokenFiles,new PersonalExportWriter(db,mapper),new AccountDeletionStages(store,brokenFiles,guard));
        for(int attempt=1;attempt<=4;attempt++){var lease=claim(broken,"delete-failure-"+attempt);broken.process(lease);assertEquals("RETRY_WAIT",db.queryForObject("SELECT status FROM mp_background_job WHERE id=?",String.class,lease.job()));assertEquals(attempt,db.queryForObject("SELECT attempt_count FROM mp_background_job WHERE id=?",Integer.class,lease.job()));assertEquals("FILES",db.queryForObject("SELECT current_stage FROM mp_account_deletion_request WHERE id=?",String.class,lease.target()));assertEquals(key,db.queryForObject("SELECT object_key FROM mp_student_data_export WHERE public_id=?",String.class,export.exportId()));due(lease.job());}
        assertEquals("ACTION_REQUIRED",service.receipt(issued.status().receiptId(),issued.secret()).status());jobs.process(claim(jobs,"disk-recovered"));assertEquals("COMPLETED",service.receipt(issued.status().receiptId(),issued.secret()).status());assertThrows(IllegalStateException.class,()->files.read(key));
    }
    @Test void guardFailurePreventsAnyFilesAndCannotBeReportedCompleted(){
        var blocked=guard;doThrow(new ApiException(503,"DELETION_SOURCE_INVALID")).when(blocked).validate(student.internalId());var observed=spy(files);var worker=worker(observed,new PersonalExportWriter(db,mapper),new AccountDeletionStages(store,observed,blocked));var issued=deletion();confirm(issued);var lease=claim(worker,"bad-ownership");worker.process(lease);verify(observed,never()).delete(any());assertEquals("FAILED",db.queryForObject("SELECT status FROM mp_account_deletion_request WHERE id=?",String.class,lease.target()));assertEquals("FILES",db.queryForObject("SELECT current_stage FROM mp_account_deletion_request WHERE id=?",String.class,lease.target()));assertEquals("DELETION_SOURCE_INVALID",db.queryForObject("SELECT failure_code FROM mp_account_deletion_request WHERE id=?",String.class,lease.target()));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM mp_student_account WHERE id=?",Integer.class,student.internalId()));
    }
    @Test void aCorruptPersonalObjectKeyCannotDeleteAnUnrelatedAdminArtifact(){
        var requested=request();var exportLease=claim(jobs,"before-prefix-corruption");jobs.process(exportLease);String own=db.queryForObject("SELECT object_key FROM mp_student_data_export WHERE public_id=?",String.class,requested.exportId());String admin="admin/"+PublicIds.next()+".csv";byte[] sentinel="foreign admin artifact must survive".getBytes(java.nio.charset.StandardCharsets.UTF_8);files.write(admin,sentinel);
        db.update("UPDATE mp_student_data_export SET object_key=? WHERE id=?",admin,exportLease.target());var issued=deletion();confirm(issued);var lease=claim(jobs,"reject-wrong-file-kind");jobs.process(lease);
        assertEquals("ACTION_REQUIRED",service.receipt(issued.status().receiptId(),issued.secret()).status());assertEquals("FILES",db.queryForObject("SELECT current_stage FROM mp_account_deletion_request WHERE id=?",String.class,lease.target()));assertArrayEquals(sentinel,files.read(admin));assertTrue(files.read(own).length>0);assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM mp_student_data_export WHERE id=?",Integer.class,exportLease.target()));
    }
    @Test void aCorruptCheckpointCannotDeleteAnotherStudentsSamePrefixArtifact(){
        request();var own=claim(jobs,"own-export-for-collision");jobs.process(own);var foreign=service.requestExport(other,new PrivacyDtos.ExportRequest("FULL_PERSONAL_EXPORT"),key());var otherLease=jobs.claim("foreign-export-for-collision");assertNotNull(otherLease);assertEquals(other.internalId(),otherLease.student());jobs.process(otherLease);byte[] expected=service.download(other,foreign.exportId());String otherKey=db.queryForObject("SELECT object_key FROM mp_student_data_export WHERE public_id=?",String.class,foreign.exportId());
        db.update("UPDATE mp_background_job SET checkpoint_json=? WHERE id=?",store.json(Map.of("phase","PUBLISHED","artifactKeys",List.of(otherKey))),own.job());var issued=deletion();confirm(issued);var lease=claim(jobs,"reject-foreign-checkpoint");jobs.process(lease);
        assertEquals("ACTION_REQUIRED",service.receipt(issued.status().receiptId(),issued.secret()).status());assertEquals("FILES",db.queryForObject("SELECT current_stage FROM mp_account_deletion_request WHERE id=?",String.class,lease.target()));assertArrayEquals(expected,service.download(other,foreign.exportId()));assertEquals("READY",service.exportStatus(other,foreign.exportId()).status());assertEquals("DELETION_PENDING",db.queryForObject("SELECT status FROM mp_student_account WHERE id=?",String.class,student.internalId()));
    }
    private static void await(CountDownLatch latch){try{if(!latch.await(8,TimeUnit.SECONDS))throw new IllegalStateException("Synthetic barrier timed out");}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException(interrupted);}}
}
